from openpyxl import load_workbook
import datetime

# Load workbook
wb = load_workbook('/root/output/rar_result.xlsx', data_only=False)

# Check Value sheet
ws_value = wb['Value']
print("VALUE SHEET ANALYSIS")
print("=" * 80)

# Get all column headers (countries)
countries_value = {}
for col_idx in range(3, ws_value.max_column + 1):  # Start from column 3 (C)
    col_letter = chr(64 + col_idx) if col_idx <= 26 else 'A' + chr(64 + col_idx - 26)
    desc = ws_value.cell(1, col_idx).value

    # Parse year from description
    if desc:
        year_found = None
        # Look for the latest year in rows 2-6
        for row_check in range(2, 7):
            cell_val = ws_value.cell(row_check, col_idx).value
            if cell_val and isinstance(cell_val, str):
                if '2025' in str(cell_val):
                    year_found = 2025
                    break
                elif '2024' in str(cell_val):
                    year_found = 2024

        # Look at actual data row to determine latest year
        latest_year = None
        latest_data_row = None
        for row_idx in range(10, ws_value.max_row + 1):
            date_cell = ws_value.cell(row_idx, 1).value
            if date_cell and isinstance(date_cell, (int, float)):
                data_val = ws_value.cell(row_idx, col_idx).value
                if data_val and isinstance(data_val, (int, float)):
                    if int(date_cell) >= 2024:
                        if latest_year is None or date_cell >= latest_year:
                            latest_year = int(date_cell)
                            latest_data_row = row_idx

        if latest_year and latest_year >= 2024:
            # Extract country name from description
            country = desc.split(':')[0].strip() if ':' in desc else desc
            countries_value[country] = {
                'col': col_idx,
                'col_letter': col_letter,
                'year': latest_year,
                'row': latest_data_row,
                'desc': desc[:100]
            }

print(f"\nCountries with 2024+ data in Value sheet:")
for country, info in sorted(countries_value.items(), key=lambda x: x[1]['year'], reverse=True):
    print(f"  {country}: Year {info['year']} (Row {info['row']})")

print(f"\nTotal countries in Value sheet with 2024+ data: {len(countries_value)}")

# Check Volume sheet
print("\n" + "=" * 80)
print("VOLUME SHEET ANALYSIS")
print("=" * 80)

